const fs = require('fs');
const data = JSON.parse(fs.readFileSync('screen.json', 'utf8'));
const words = data.words;
// find first word with start near 2.4 and text Hey
let startIdx = words.findIndex(w => w.type==='word' && w.text.toLowerCase().includes('hey'));
console.log('startIdx', startIdx);
// print words from startIdx to some words after customer.
let out = [];
let collecting = false;
for (let i = startIdx; i < words.length; i++) {
  out.push(words[i]);
  if (words[i].type==='word' && words[i].text.toLowerCase().includes('customer')) break;
}
console.log(JSON.stringify(out, null, 2));
"

