cat > gen_stars.js << 'EOF'
// Seeded PRNG (mulberry32) for deterministic "random-looking" star field authored once.
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(88422);

const W = 1920, H = 1080;
const COMP_DURATION = 8.16;
const N = 58;

// Reject-sample against a min-distance grid-ish check to avoid tight clusters,
// while keeping placement irregular (not a grid, not rows).
const pts = [];
function farEnough(x, y, minD) {
  for (const p of pts) {
    const dx = p.x - x, dy = p.y - y;
    if (dx * dx + dy * dy < minD * minD) return false;
  }
  return true;
}

let attempts = 0;
while (pts.length < N && attempts < N * 200) {
  attempts++;
  const x = Math.round(rand() * W);
  const y = Math.round(rand() * H);
  if (farEnough(x, y, 55)) pts.push({ x, y });
}

// Pick exactly 2 warm-tinted stars, ~9 "bright/larger" stars, rest tiny cool white/blue-white.
const warmIdx = new Set();
while (warmIdx.size < 2) warmIdx.add(Math.floor(rand() * pts.length));
const brightIdx = new Set();
while (brightIdx.size < 9) {
  const i = Math.floor(rand() * pts.length);
  if (!warmIdx.has(i)) brightIdx.add(i);
}

const coolColors = ["#ffffff", "#eaf3ff", "#dbe8ff", "#cfe0ff"];
const warmColors = ["#fff1c9", "#ffe9b0"];

const stars = pts.map((p, i) => {
  const isWarm = warmIdx.has(i);
  const isBright = brightIdx.has(i);
  const size = isBright ? +(2.6 + rand() * 1.6).toFixed(2) : +(1.2 + rand() * 1.2).toFixed(2);
  const glow = isBright ? +(7 + rand() * 7).toFixed(1) : +(2 + rand() * 3).toFixed(1);
  const color = isWarm ? warmColors[Math.floor(rand() * warmColors.length)] : coolColors[Math.floor(rand() * coolColors.length)];
  const peak = isBright ? +(0.85 + rand() * 0.15).toFixed(2) : +(0.45 + rand() * 0.35).toFixed(2);
  const trough = +(peak * (0.15 + rand() * 0.2)).toFixed(2);
  const half = +(0.7 + rand() * 1.6).toFixed(2); // half-cycle (up or down) duration in seconds
  const delay = +(rand() * 3.2).toFixed(2); // stagger so twinkles don't sync
  const cycles = Math.max(2, Math.ceil((COMP_DURATION - delay) / (half * 2)) + 1);
  return { x: p.x, y: p.y, size, glow, color, peak, trough, half, delay, cycles, isBright, isWarm };
});

console.log(JSON.stringify(stars));
EOF
node gen_stars.js > stars.json
